import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u09")
C = "B1-B2"
# Lições de aprofundamento (10–25): mais expressões idiomáticas por tema.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)

L(10, "Trabalho: arrancar e acelerar", "Een tandje bijzetten.",
  ["Usar expressões sobre esforço e iniciativa no trabalho"],
  vocab=[X("v-op-poten-zetten","iets op poten zetten","montar algo (do zero)"), X("v-tandje-bijzetten","een tandje bijzetten","acelerar o ritmo|esforçar-se mais"),
         X("v-kantjes-eraf","de kantjes eraf lopen","fazer o mínimo|baldar-se")],
  ex=[("Ze heeft in een jaar een heel bedrijf op poten gezet.","Num ano ela montou uma empresa inteira."),("We moeten een tandje bijzetten om de deadline te halen.","Temos de acelerar o ritmo para cumprir o prazo."),("Hij loopt de kantjes eraf; het werk is nooit af.","Ele faz o mínimo; o trabalho nunca está acabado.")],
  review=["v-handen-uit-de-mouwen"],
  cefr=C, exs=[
    MA([("iets op poten zetten","montar algo"),("een tandje bijzetten","acelerar"),("de kantjes eraf lopen","fazer o mínimo"),("de handen uit de mouwen steken","arregaçar as mangas")], "Trabalho.", ["v-op-poten-zetten","v-tandje-bijzetten","v-kantjes-eraf","v-handen-uit-de-mouwen"]),
    EX("een tandje bijzetten", "pôr mais um dente (da engrenagem)", "O que significa?", ["*acelerar, esforçar-se mais","ir ao dentista|Literal.","abrandar|É o contrário."], "Imagem: mudança de velocidade.", ["v-tandje-bijzetten"]),
    EX("de kantjes eraf lopen", "correr pelas beirinhas", "O que significa?", ["*fazer só o mínimo","trabalhar muito|É o contrário.","correr uma maratona|Literal."], "Imagem: cortar caminho.", ["v-kantjes-eraf"]),
    TR("pt-nl","Temos de acelerar o ritmo.", ["We moeten een tandje bijzetten","Wij moeten een tandje bijzetten"], "Expressão.", ["v-tandje-bijzetten"]),
    TR("nl-pt","Ze heeft een bedrijf op poten gezet.", ["Ela montou uma empresa","Ela criou uma empresa do zero"], "op poten zetten.", ["v-op-poten-zetten"]),
    FB("Als we de deadline willen halen, moeten we een tandje ___.", ["bijzetten"], "Separável no infinitivo.", ["v-tandje-bijzetten"], choices=["bijzetten","bijgezet","zetten bij"], tr="Se quisermos cumprir o prazo, temos de acelerar."),
    FE(["Hij","loopt","de","kantjes","erop."], 4, "eraf.", "Expressão: de kantjes eraf lopen.", ["v-kantjes-eraf"]),
    DL([("Leidinggevende","We liggen achter op schema.","Estamos atrasados no calendário."),("Jij","","")], ["*Dan zetten we deze week een tandje bij; ik kan ook zaterdag even werken.","Ik loop de kantjes eraf.|Não ajuda.","Op poten.|Incompleto."], "Reagir.", ["v-tandje-bijzetten"]),
    LI("Wie de kantjes eraf loopt, valt vroeg of laat door de mand.", ["Wie de kantjes eraf loopt, valt vroeg of laat door de mand","Wie de kantjes eraf loopt valt vroeg of laat door de mand"], "Quem faz o mínimo, mais cedo ou mais tarde é desmascarado.", "Combinação.", ["v-kantjes-eraf","v-door-de-mand-vallen"]),
  ], diff=4, mins=5)

